func TestShipcheckPublicApprovalFileRejectsInvalidApprovals(t *testing.T) {
	withShipcheckCleanCommit(t, "1111111111111111111111111111111111111111")
	tests := []struct {
		name      string
		overrides map[string]any
		want      string
	}{
		{
			name:      "missing approval",
			overrides: map[string]any{"owner_approval": nil},
			want:      "owner_approval",
		},
		{
			name:      "false approval",
			overrides: map[string]any{"desktop_mcp": false},
			want:      "desktop_mcp",
		},
		{
			name:      "unknown top-level field",
			overrides: map[string]any{"unexpected": true},
			want:      "unknown field",
		},
		{
			name:      "token literal",
			overrides: map[string]any{"evidence": map[string]any{"owner_approval": "Bearer fixture-token"}},
			want:      "token literals",
		},
		{
			name:      "commit mismatch",
			overrides: map[string]any{"local_preview_commit": "0000000000000000000000000000000000000000"},
			want:      "local_preview_commit",
		},
		{
			name:      "unknown evidence field",
			overrides: map[string]any{"evidence": map[string]any{"unexpected": "not part of public launch approval"}},
			want:      "unexpected",
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			approvalPath := writeShipcheckPublicApprovalFile(t, tc.overrides)

			_, _, err := runCLIForDocsTest(t, "shipcheck", "public", "--approval-file", approvalPath, "--json")
			if err == nil {
				t.Fatalf("shipcheck public should reject invalid approval file")
			}
			if !strings.Contains(strings.ToLower(err.Error()), strings.ToLower(tc.want)) {
				t.Fatalf("error should mention %q, got %v", tc.want, err)
			}
		})
	}
}

