func TestShipcheckLocalFakeMCPSuccess(t *testing.T) {
	binary := writeFakeMCPBinary(t, requiredShipcheckMCPTools())

	stdout, stderr, err := runCLIForDocsTest(t, "shipcheck", "local", "--mcp-binary", binary, "--json")
	if err != nil {
		t.Fatalf("shipcheck local fake MCP returned error: %v", err)
	}
	if stderr != "" {
		t.Fatalf("shipcheck local fake MCP wrote stderr: %q", stderr)
	}

	var got shipcheckLocalResponse
	if err := json.Unmarshal([]byte(stdout), &got); err != nil {
		t.Fatalf("shipcheck local fake MCP emitted invalid JSON: %v\n%s", err, stdout)
	}
	if !got.Passed {
		t.Fatalf("shipcheck local fake MCP should pass: %#v", got)
	}
	if !got.Safety.ChildProcessExecuted || !got.Safety.ChildEnvAllowlisted || got.Safety.ChildProcessSandboxed {
		t.Fatalf("shipcheck local fake MCP should state child process was executed with allowlisted env and no sandbox: %#v", got.Safety)
	}
	if got.Safety.NoAPICalls || got.Safety.NoSecretsRead || got.Safety.NoGitHubCalls || got.Safety.NoNPMCalls || got.Safety.NoHomebrewCalls {
		t.Fatalf("shipcheck local fake MCP should not overclaim child-process behavior: %#v", got.Safety)
	}
	check := shipcheckCheckByName(t, got.Checks, "mcp_tools")
	if !check.Passed {
		t.Fatalf("mcp_tools should pass: %#v", check)
	}
	for _, want := range requiredShipcheckMCPTools() {
		if !containsString(check.Evidence, want) {
			t.Fatalf("mcp_tools evidence missing %q: %#v", want, check.Evidence)
		}
	}
	if strings.Contains(stdout, binary) {
		t.Fatalf("shipcheck local should not print local binary paths:\n%s", stdout)
	}
}

func TestShipcheckLocalFakeMCPMissingRequiredToolFails(t *testing.T) {
	tools := []string{}
	for _, name := range requiredShipcheckMCPTools() {
		if name != "release_plan" {
			tools = append(tools, name)
		}
	}
	binary := writeFakeMCPBinary(t, tools)

	stdout, _, err := runCLIForDocsTest(t, "shipcheck", "local", "--mcp-binary", binary, "--json")
	if err == nil {
		t.Fatalf("shipcheck local should fail when MCP tool is missing")
	}
	if !strings.Contains(err.Error(), "release_plan") {
		t.Fatalf("error should mention missing release_plan, got %v", err)
	}
	var got shipcheckLocalResponse
	if unmarshalErr := json.Unmarshal([]byte(stdout), &got); unmarshalErr != nil {
		t.Fatalf("failed shipcheck should still emit JSON: %v\n%s", unmarshalErr, stdout)
	}
	if got.Passed {
		t.Fatalf("shipcheck should not pass with missing MCP tool: %#v", got)
	}
	check := shipcheckCheckByName(t, got.Checks, "mcp_tools")
	if check.Passed || !strings.Contains(check.Note, "release_plan") {
		t.Fatalf("mcp_tools should record missing release_plan: %#v", check)
	}
}

func TestShipcheckLocalRejectsDeliverBeforeDelivery(t *testing.T) {
	target := filepath.Join(t.TempDir(), "shipcheck-delivery.json")
	home := t.TempDir()
	t.Setenv("HOME", home)

	oldArgs := os.Args
	t.Cleanup(func() {
		os.Args = oldArgs
	})
	os.Args = []string{
		"straddle-pp-cli",
		"shipcheck",
		"local",
		"--deliver",
		"file:" + target,
		"--profile",
		"missing-profile",
	}

	err := Execute()
	if err == nil {
		t.Fatalf("shipcheck local should reject --deliver")
	}
	if !strings.Contains(err.Error(), "shipcheck local does not support --deliver") {
		t.Fatalf("error should explain --deliver is unsupported, got %v", err)
	}
	if _, statErr := os.Stat(target); !os.IsNotExist(statErr) {
		t.Fatalf("shipcheck local should reject --deliver before writing output, stat err=%v", statErr)
	}
	if _, statErr := os.Stat(filepath.Join(home, ".straddle-pp-cli")); !os.IsNotExist(statErr) {
		t.Fatalf("shipcheck local should reject --deliver before loading profile state, stat err=%v", statErr)
	}
}

func TestShipcheckLocalRejectsSecretLiteralMCPBinary(t *testing.T) {
	_, _, err := runCLIForDocsTest(t, "shipcheck", "local", "--mcp-binary", "straddle-pp-mcp --token sk_test_fixture", "--json")
	if err == nil {
		t.Fatalf("shipcheck local should reject token literals in --mcp-binary")
	}
	var cliErr *cliError
	if !errors.As(err, &cliErr) || cliErr.code != 2 {
		t.Fatalf("token literal rejection should be a usage error, got %#v", err)
	}
	if !strings.Contains(strings.ToLower(err.Error()), "token") {
		t.Fatalf("error should mention token literal rejection, got %v", err)
	}
}

func shipcheckCheckByName(t *testing.T, checks []shipcheckCheck, name string) shipcheckCheck {
	t.Helper()
	for _, check := range checks {
		if check.Name == name {
			return check
		}
	}
	t.Fatalf("missing check %q in %#v", name, checks)
	return shipcheckCheck{}
}

type shipcheckProvenanceFixtureConfig struct {
	SourcePath string
	Checksum   string
	MCPBinary  string
}

func writeShipcheckProvenanceFixture(t *testing.T, sourceOpenAPI string, transformedSpec string) (string, string) {
	t.Helper()
	tempDir := t.TempDir()
	packageDir := filepath.Join(tempDir, "repo", "packages", "cli", "straddle-pp-cli")
	if err := os.MkdirAll(filepath.Join(packageDir, "internal", "cli"), 0o755); err != nil {
		t.Fatalf("create fixture package dir: %v", err)
	}
	sourcePath := shipcheckProvenanceFixtureSourcePath(packageDir)
	if err := os.MkdirAll(filepath.Dir(sourcePath), 0o755); err != nil {
		t.Fatalf("create fixture docs dir: %v", err)
	}
	if err := os.WriteFile(sourcePath, []byte(sourceOpenAPI), 0o644); err != nil {
		t.Fatalf("write fixture source OpenAPI: %v", err)
	}
	if err := os.WriteFile(filepath.Join(packageDir, "spec.json"), []byte(transformedSpec), 0o644); err != nil {
		t.Fatalf("write transformed spec fixture: %v", err)
	}
	sourceHash := sha256StringHex(sourceOpenAPI)
	writeShipcheckPrintingPressConfig(t, packageDir, shipcheckProvenanceFixtureConfig{
		SourcePath: sourcePath,
		Checksum:   "sha256:" + sourceHash,
	})
	return packageDir, sourceHash
}

func shipcheckProvenanceFixtureSourcePath(packageDir string) string {
	return filepath.Clean(filepath.Join(packageDir, "..", "..", "..", "straddle", "sdks", "straddle-docs", "docs", "api-reference", "openapi.json"))
}

func writeShipcheckPrintingPressConfig(t *testing.T, packageDir string, config shipcheckProvenanceFixtureConfig) {
	t.Helper()
	mcpBinary := config.MCPBinary
	if mcpBinary == "" {
		mcpBinary = "straddle-pp-mcp"
	}
	raw, err := json.MarshalIndent(map[string]any{
		"printing_press_version": "4.2.0",
		"printer_name":           "hello-keith",
		"spec_path":              config.SourcePath,
		"spec_url":               config.SourcePath,
		"spec_checksum":          config.Checksum,
		"mcp_binary":             mcpBinary,
	}, "", "  ")
	if err != nil {
		t.Fatalf("marshal fixture .printing-press.json: %v", err)
	}
	if err := os.WriteFile(filepath.Join(packageDir, ".printing-press.json"), raw, 0o644); err != nil {
		t.Fatalf("write fixture .printing-press.json: %v", err)
	}
}

func copyShipcheckFixtureFile(t *testing.T, source string, target string) {
	t.Helper()
	raw, err := os.ReadFile(source)
	if err != nil {
		t.Fatalf("read fixture file %s: %v", source, err)
	}
	if err := os.WriteFile(target, raw, 0o644); err != nil {
		t.Fatalf("copy fixture file to %s: %v", target, err)
	}
}

func writeShipcheckExecutableFixture(t *testing.T, path string) {
	t.Helper()
	if err := os.WriteFile(path, []byte("#!/bin/sh\nexit 0\n"), 0o755); err != nil {
		t.Fatalf("write executable fixture %s: %v", path, err)
	}
}

func sha256StringHex(value string) string {
	sum := sha256.Sum256([]byte(value))
	return hex.EncodeToString(sum[:])
}

func shipcheckEvidenceContains(evidence []string, want string) bool {
	for _, item := range evidence {
		if strings.Contains(item, want) {
			return true
		}
	}
	return false
}

func withShipcheckCleanCommit(t *testing.T, commit string) {
	t.Helper()

	oldReadBuildInfo := shipcheckReadBuildInfo
	oldWorktreeModified := shipcheckWorktreeModified
	shipcheckReadBuildInfo = func() (*debug.BuildInfo, bool) {
		return &debug.BuildInfo{Settings: []debug.BuildSetting{
			{Key: "vcs.revision", Value: commit},
			{Key: "vcs.modified", Value: "false"},
		}}, true
	}
	shipcheckWorktreeModified = func(string) (bool, error) {
		return false, nil
	}
	t.Cleanup(func() {
		shipcheckReadBuildInfo = oldReadBuildInfo
		shipcheckWorktreeModified = oldWorktreeModified
	})
}

func writeShipcheckPublicApprovalFile(t *testing.T, overrides map[string]any) string {
	t.Helper()

	commit, err := currentShipcheckGitCommit()
	if err != nil {
		t.Fatalf("get current git commit for approval fixture: %v", err)
	}
	evidence := map[string]any{}
	for _, name := range requiredShipcheckPublicApprovals() {
		evidence[name] = name + " approved in local test fixture"
	}
	approval := map[string]any{
		"approver":             "Public Launch Approver",
		"approved_at":          "2026-05-10T00:00:00Z",
		"local_preview_commit": commit,
		"owner_approval":       true,
		"public_distribution":  true,
		"docs_support":         true,
		"desktop_mcp":          true,
		"live_smoke":           true,
		"signing_notarization": true,
		"evidence":             evidence,
	}
	for key, value := range overrides {
		if value == nil {
			delete(approval, key)
			continue
		}
		approval[key] = value
	}

	data, err := json.Marshal(approval)
	if err != nil {
		t.Fatalf("marshal public approval file: %v", err)
	}
	path := filepath.Join(t.TempDir(), "public-approval.json")
	if err := os.WriteFile(path, data, 0o600); err != nil {
		t.Fatalf("write public approval file: %v", err)
	}
	return path
}
